import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.C-zpCNjM.js";var i=JSON.parse(`{"title":"Insert & Remove HTML","description":"","frontmatter":{"prev":{"text":"Fetch Google Sheet Data","link":"/documentation/field-types/google-service-sheet/fetch-google-sheet-data"},"next":{"text":"Page Loading","link":"/documentation/field-types/others/page-loading"}},"headers":[],"relativePath":"documentation/field-types/others/insert-remove-html.md","filePath":"documentation/field-types/others/insert-remove-html.md","lastUpdated":1788551488000}`),a={name:`documentation/field-types/others/insert-remove-html.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="insert-remove-html" tabindex="-1">Insert &amp; Remove HTML <a class="header-anchor" href="#insert-remove-html" aria-label="Permalink to “Insert &amp; Remove HTML”">​</a></h1><p>The <strong>Insert &amp; Remove HTML</strong> field type allows direct DOM tree manipulation—either injecting custom HTML elements into a target web page or removing unwanted overlays, popups, and banners during automation.</p><hr><h2 id="configuration-options" tabindex="-1">Configuration Options <a class="header-anchor" href="#configuration-options" aria-label="Permalink to “Configuration Options”">​</a></h2><table tabindex="0"><thead><tr><th>Option</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><strong>Selector Query</strong></td><td>Text</td><td>CSS selector or XPath targeting the reference DOM element.</td></tr><tr><td><strong>Position of New HTML Content</strong></td><td>Dropdown</td><td>Where new HTML is injected relative to the target element.</td></tr><tr><td><strong>Field Value / Default Value</strong></td><td>Text / HTML</td><td>The HTML markup to insert (supports static text or Excel <code>{$Column$}</code> variables).</td></tr><tr><td><strong>Remove exist element html before insert html</strong></td><td>Switch</td><td>Clears the target element&#39;s existing inner HTML before inserting new content.</td></tr><tr><td><strong>Remove element</strong></td><td>Switch</td><td>Completely removes the targeted element from the DOM (<code>element.remove()</code>). Disables insertion options when active.</td></tr></tbody></table><hr><h2 id="positions" tabindex="-1">Insertion Positions <a class="header-anchor" href="#positions" aria-label="Permalink to “Insertion Positions”">​</a></h2><table tabindex="0"><thead><tr><th>Position</th><th>Relative Placement</th><th>DOM Result</th></tr></thead><tbody><tr><td><strong>beforebegin</strong></td><td>Outside the element, immediately before it.</td><td><code>[NEW] &lt;element&gt;...&lt;/element&gt;</code></td></tr><tr><td><strong>afterbegin</strong></td><td>Inside the element, as its first child.</td><td><code>&lt;element&gt;[NEW] existing...&lt;/element&gt;</code></td></tr><tr><td><strong>beforeend</strong></td><td>Inside the element, as its last child.</td><td><code>&lt;element&gt;existing... [NEW]&lt;/element&gt;</code></td></tr><tr><td><strong>afterend</strong></td><td>Outside the element, immediately after it.</td><td><code>&lt;element&gt;...&lt;/element&gt; [NEW]</code></td></tr><tr><td><strong>innerHTML</strong></td><td>Replaces all inner content of the target element.</td><td><code>&lt;element&gt;[NEW]&lt;/element&gt;</code></td></tr></tbody></table><hr><h2 id="examples" tabindex="-1">Common Use Cases <a class="header-anchor" href="#examples" aria-label="Permalink to “Common Use Cases”">​</a></h2><h3 id="_1-adding-a-new-option-to-a-select-dropdown" tabindex="-1">1. Adding a New Option to a <code>&lt;select&gt;</code> Dropdown <a class="header-anchor" href="#_1-adding-a-new-option-to-a-select-dropdown" aria-label="Permalink to “1. Adding a New Option to a &lt;select&gt; Dropdown”">​</a></h3><p>Inject a missing <code>&lt;option&gt;</code> into an existing dropdown so it can be selected in subsequent steps:</p><ul><li><strong>Selector Query</strong>: <code>select[name=&quot;category&quot;]</code></li><li><strong>Position</strong>: <code>beforeend</code></li><li><strong>Field Default Value</strong>: <code>&lt;option value=&quot;1000&quot;&gt;1000&lt;/option&gt;</code></li></ul><h3 id="_2-removing-popups-cookie-banners-overlays" tabindex="-1">2. Removing Popups, Cookie Banners &amp; Overlays <a class="header-anchor" href="#_2-removing-popups-cookie-banners-overlays" aria-label="Permalink to “2. Removing Popups, Cookie Banners &amp; Overlays”">​</a></h3><p>Remove intrusive overlays or modal backdrops that block automated clicks:</p><ul><li><strong>Selector Query</strong>: <code>.modal-backdrop, #cookie-banner, .popup-overlay</code></li><li><strong>Remove element</strong>: <strong>ON</strong></li></ul><h3 id="_3-injecting-a-status-or-alert-banner" tabindex="-1">3. Injecting a Status or Alert Banner <a class="header-anchor" href="#_3-injecting-a-status-or-alert-banner" aria-label="Permalink to “3. Injecting a Status or Alert Banner”">​</a></h3><p>Add helper notifications or instructions inside a page container:</p><ul><li><strong>Selector Query</strong>: <code>#main-container</code></li><li><strong>Position</strong>: <code>afterbegin</code></li><li><strong>Field Default Value</strong>: <code>&lt;div class=&quot;alert alert-info&quot;&gt;Processing batch: {$BatchId$}&lt;/div&gt;</code></li></ul><hr><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to “Troubleshooting”">​</a></h2><table tabindex="0"><thead><tr><th>Issue</th><th>Likely Cause</th><th>Solution</th></tr></thead><tbody><tr><td><strong>Content does not appear</strong></td><td>Selector failed to locate element or loaded late</td><td>Inspect element using <kbd>Alt</kbd> + <kbd>Shift</kbd> + <kbd>I</kbd>. Add a delay before this field if element renders via AJAX.</td></tr><tr><td><strong>Element not removed</strong></td><td>Target is inside an iframe or selector didn&#39;t match</td><td>Ensure selector accurately matches and active iframe context is configured.</td></tr><tr><td><strong>Duplicate content on replay</strong></td><td>Looping or re-running without clearing previous content</td><td>Turn ON <strong>Remove exist element html before insert html</strong> or use <strong>innerHTML</strong> position.</td></tr></tbody></table><hr><h2 id="related" tabindex="-1">Related Documentation <a class="header-anchor" href="#related" aria-label="Permalink to “Related Documentation”">​</a></h2><ul><li><img src="/svg/form.svg" class="doc-icon"> <a href="/documentation/field-types/select.html">Select Field</a> — Dropdown automation and option management</li><li><img src="/svg/code.svg" class="doc-icon"> <a href="/documentation/field-types/javascript-code.html">JavaScript Code Field</a> — Advanced DOM scripting</li><li><img src="/svg/settings.svg" class="doc-icon"> <a href="/documentation/form-fields/field-settings.html">Field Settings</a> — Advanced execution options</li><li><img src="/svg/click.svg" class="doc-icon"> <a href="/documentation/locate-element.html">Locate Element</a> — Element selector tools</li></ul>`,25)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};